class Stack:
    def __init__(self):
        self._items = []

    def push(self, x):
        self._items.append(x)

    def peek(self):
        if not self._items:
            raise IndexError("빈 스택")
        return self._items[-1]

    def __len__(self):
        return len(self._items)


def check(values):
    s = Stack()
    for v in values:
        s.push(v)
    return [s.peek(), len(s)]

